package logos

import (
	"encoding/json"
	"os"
	"path/filepath"
)

// EditMapSuffix is appended to the name of an ejected Go file to name its
// edit map: a.lgo ejects to a.go and a.go.edits.
const EditMapSuffix = ".edits"

// EditMapVersion is the version field of an EditMap. A reader rejects any
// other value. Version 2 added Segments; the Edits array alone cannot
// tell a generated byte from a copied one, so a reader of a version 2
// map makes every origin decision through Segments.
const EditMapVersion = 2

// Segment is one run of the ejected text: the Len bytes at Out are
// either a verbatim copy of the Len bytes of the original file at Orig,
// or, with Orig negative, compiler-generated. The segments of one edit
// map partition [0, Out) of the ejected text in order.
type Segment struct {
	Out  int `json:"out"`
	Len  int `json:"len"`
	Orig int `json:"orig"` // -1 marks generated bytes
}

// EditMap is the JSON document beside an ejected file. It lists the edits
// that turned the original source into the ejected text, as byte spans of
// the original, so a reader can map any offset of one text to the other
// (the language server proxy does this for positions). Source is the base
// name of the original file, Size and Out are the byte sizes of the
// original and ejected texts; a reader checks them against the texts it
// holds before it trusts the spans.
type EditMap struct {
	Version int        `json:"version"`
	Source  string     `json:"source"`
	Size    int        `json:"size"`
	Out     int        `json:"out"`
	Edits   []EditSpan `json:"edits"`
	// Segments partition the ejected text into copied and generated
	// runs. Edits stays for the size arithmetic and the coarse layout.
	Segments []Segment `json:"segments"`
}

// writeEditMap writes the edit map of one ejected file to path. It uses
// encoding/json, not encoding/json/v2: the bootstrap toolchain builds this
// package, and v2 is an experiment there.
func writeEditMap(path, source string, size, out int, spans []EditSpan, segments []Segment) error {
	data, err := json.Marshal(EditMap{
		Version:  EditMapVersion,
		Source:   filepath.Base(source),
		Size:     size,
		Out:      out,
		Edits:    spans,
		Segments: segments,
	})
	if err != nil {
		return err
	}
	return os.WriteFile(path, append(data, '\n'), 0o666)
}

// segmentsOf builds the origin segments of a whole edited text from the
// splices that produced it, already sorted by applyChunks: every gap
// between splices is a verbatim copy of the original at the same
// offsets, a splice without chunks is one generated run, and the chunks
// of a splice text cut it into copied and generated runs. Adjacent runs
// of equal kind merge, so an unchanged file is a single copy segment.
func segmentsOf(sorted []splice, outLen int) []Segment {
	var segs []Segment
	seg := func(start, end, orig int) {
		if end <= start {
			return
		}
		if n := len(segs); n > 0 {
			last := &segs[n-1]
			if (last.Orig < 0 && orig < 0) ||
				(last.Orig >= 0 && orig >= 0 && last.Orig+last.Len == orig && last.Out+last.Len == start) {
				last.Len += end - start
				return
			}
		}
		segs = append(segs, Segment{Out: start, Len: end - start, Orig: orig})
	}
	out := 0
	prev := 0
	for _, s := range sorted {
		seg(out, out+(s.start-prev), prev) // gap: copy at identical offsets
		out += s.start - prev
		cov := 0
		for _, ch := range s.chunks {
			if ch.n == 0 {
				continue
			}
			if ch.out > cov {
				seg(out+cov, out+ch.out, -1) // generated run before the chunk
			}
			seg(out+ch.out, out+ch.out+ch.n, ch.orig)
			cov = ch.out + ch.n
		}
		if cov < len(s.text) {
			seg(out+cov, out+len(s.text), -1) // generated tail
		}
		out += len(s.text)
		prev = s.end
	}
	seg(out, outLen, prev)
	return segs
}
